"""Documentacao da 220a leva. Uso: python docs.py"""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'engenharia-reversa'))
from gen_docs import fazer, leia, cadeia, prova_save, REF_JOGO, CARREIRA_PT, CARREIRA_EN

N = 220
R = [('criar_jogo_pela_configuracao', 'create_game_from_setup_file', '0x827110', 'Setup.cpp', 'cdecl', 'lê o auto_setup.cfg/quick_start.cfg (banco, estatísticas, ligas de frente e de fundo, idioma, motor, propostas, férias), cria o jogo (0x828110) e grava o .qst (0x82e430 com 0x17) e libera tudo, ou põe o técnico humano de férias num clube sorteado', 'reads auto_setup.cfg/quick_start.cfg (database, stats, foreground and background leagues, language, engine, bids, holiday), creates the game (0x828110) and saves the .qst (0x82e430 with 0x17) and frees everything, or puts the human manager on holiday at a drawn club'), ('gravar_jogo', 'save_game_data', '0x82e430', 'Setup.cpp', 'cdecl', 'grava o save: apaga o antigo, o banco (0x524d30), o general.dat (16 campos e o resumo), o save dos subsistemas na ordem da original com disco e memória entre eles, empacota os *.tmp, as regras FIFA; em rede, grava em temp_save_file e renomeia', 'saves the game: deletes the old file, the database (0x524d30), general.dat (16 fields and the summary), the subsystem saves in the original order with disk and memory checks between them, packs the *.tmp files, the FIFA rules; on a network game, writes to temp_save_file and renames')]
ESCAPADAS = {  # nome: (explicação pt, explicação en)
    'sv3_criar_id': ('a cópia da 0x827110 está desligada (DESLIGADAS: rodando na pilha particular, ela muda o resíduo que a create_game 0x828110 lê e o club.dat sai diferente), então a mutação não roda', 'the 0x827110 copy is switched off (DESLIGADAS: running on the private stack it changes the residue create_game 0x828110 reads and club.dat comes out different), so the mutation does not run'),
    'sv3_criar_frente': ('a cópia da 0x827110 está desligada (DESLIGADAS: rodando na pilha particular, ela muda o resíduo que a create_game 0x828110 lê e o club.dat sai diferente), então a mutação não roda', 'the 0x827110 copy is switched off (DESLIGADAS: running on the private stack it changes the residue create_game 0x828110 reads and club.dat comes out different), so the mutation does not run'),
}
tot, ac, esc, ok = cadeia(N)
assert ok, 'cadeia sem a referencia'
assert set(esc) <= set(ESCAPADAS), ('explicar as escapadas', esc)
lac_pt = ' '.join(f'`{e}` escapou: {ESCAPADAS[e][0]}.' for e in esc) + (' (lacuna em `PENDENCIAS.md`)' if esc else '')
lac_en = ' '.join(f'`{e}` escaped: {ESCAPADAS[e][1]}.' for e in esc) + (' (gap in `PENDENCIAS.en.md`)' if esc else '')
PS = prova_save(N)  # leva do save: mutações e prova pelo .qst gravado com e sem as rotinas (cadeia.sh)
VIA_PT = 'pela prova do save' if PS else 'pela carreira até 2002-06-01, confirmando no modo comparação as que escapam'
VIA_EN = 'by the save proof' if PS else 'by the career to 2002-06-01, confirming the escaped ones in comparison mode'
PS_PT = f'Prova do save (o .qst com e sem as rotinas): {PS}. ' if PS else ''
PS_EN = f'Save proof (the .qst with and without the routines): {PS.replace("IGUAL", "EQUAL").replace("DIFERENTE", "DIFFERENT")}. ' if PS else ''
M = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_PT}): {ac} acusadas. {lac_pt} {PS_PT}"
     f"Jogo real comparando até 2002-01-01: 0 divergências ({REF_JOGO}). Carreiras Rust ×2 e original até 2002-06-01: {CARREIRA_PT}")
ME = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_EN}): {ac} caught. {lac_en} {PS_EN}"
      f"Real game comparing to 2002-01-01: 0 divergences ({REF_JOGO}). Rust ×2 and original careers to 2002-06-01: {CARREIRA_EN}")
fazer(N, 575, 575 + len(R), 'o save: criar o jogo pelo arquivo de configuração (o início rápido e a carreira automática); o save: gravar o jogo inteiro', 'the saved game: creating the game from the setup file (quick start and automatic career); the saved game: saving the whole game',
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, d, _ in R],
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, _, d in R],
      M, ME, [(a, g) for a, g, *_ in R], "'posicao_no_conteiner': 'position_in_container',", secao=('Simulação', 'Simulation'))
leia(N, 'o save: criar o jogo pelo arquivo de configuração (o início rápido e a carreira automática); o save: gravar o jogo inteiro', 'the saved game: creating the game from the setup file (quick start and automatic career); the saved game: saving the whole game', [(a, e, f + ', ' + c, dp, de) for a, _, e, f, c, dp, de in R], tot, ac, lac_pt, lac_en,
     campos=[('[0xae3138] opções do jogo (game.cfg) +4: bit 2 (o tipo das ligas); valor; lê; +0x113: nome do jogo ("auto_setup_game"); texto; grava (criar_jogo_pela_configuracao)', '[0xae3138] game options (game.cfg) +4: bit 2 (league type); value; reads; +0x113: game name ("auto_setup_game"); text; writes (criar_jogo_pela_configuracao)'), ('nação +0x11c: marca da liga (de frente 2 ou 6, de fundo 1 ou 5, pelo bit 2 das opções); valor; lê e grava (criar_jogo_pela_configuracao)', 'nation +0x11c: league mark (foreground 2 or 6, background 1 or 5, by options bit 2); value; reads and writes (criar_jogo_pela_configuracao)'), ('[0xae2d00] ligas marcadas, [0xae2d04] ligas de frente; valor; grava; [0xae2d08] nação padrão; ponteiro; grava (criar_jogo_pela_configuracao)', '[0xae2d00] marked leagues, [0xae2d04] foreground leagues; value; writes; [0xae2d08] default nation; pointer; writes (criar_jogo_pela_configuracao)'), ('[0xa5a390] motor da partida ligado (byte), [0x9cd1f8] propostas do computador; valor; grava (criar_jogo_pela_configuracao)', '[0xa5a390] match engine enabled (byte), [0x9cd1f8] computer bids; value; writes (criar_jogo_pela_configuracao)'), ('[0xdd7124], [0xdd713c], [0xdd7130] marcas do jogo; valor; grava 1 (criar_jogo_pela_configuracao)', '[0xdd7124], [0xdd713c], [0xdd7130] game flags; value; writes 1 (criar_jogo_pela_configuracao)'), ('humano da vez 0xb74c26 + 0x300 × (i16)[0xb77c7a]: pessoa do técnico; ponteiro; lê e grava (criar_jogo_pela_configuracao)', 'current human 0xb74c26 + 0x300 × (i16)[0xb77c7a]: manager person; pointer; reads and writes (criar_jogo_pela_configuracao)'), ('pessoa (0x6e) +0x5f: humano (1); valor; lê e grava; +0x18 ano 1966, +0x10 data, +0x24 e +0x39 = 0, +0xc texto zerado; +0x1a nação; ponteiro; +4 e +8 nomes; id; grava (criar_jogo_pela_configuracao)', 'person (0x6e) +0x5f: human (1); value; reads and writes; +0x18 year 1966, +0x10 date, +0x24 and +0x39 = 0, +0xc text cleared; +0x1a nation; pointer; +4 and +8 names; id; writes (criar_jogo_pela_configuracao)'), ('clube (0x245) +0x53: nação; ponteiro; lê (criar_jogo_pela_configuracao)', 'club (0x245) +0x53: nation; pointer; reads (criar_jogo_pela_configuracao)'), ('[0xdd7110] versão do save (0xfffc1fb9); valor; grava (gravar_jogo)', '[0xdd7110] save version (0xfffc1fb9); value; writes (gravar_jogo)'), ('general.dat: [0xdd7110] versão, resumo (0xf74), [0xdd7120] id único, [0xdd7114] tamanho do banco (1 byte), [0xdd6ec8] e [0xae2c90] datas, [0xae2c88] hora, [0xae2c78] última data, [0xae2cfc] última hora, [0xae2d00] e [0xae2d04] ligas, nação padrão (id em +0 de [0xae2d08] ou −1), [0xae2d10] × 0x4f de [0xae2d0c], [0xae2d18] × 6 de [0xae2d14], [0xae235c] × 4 de [0xae2d1c]; bytes; lê e grava no save (gravar_jogo)', 'general.dat: [0xdd7110] version, summary (0xf74), [0xdd7120] unique id, [0xdd7114] database size (1 byte), [0xdd6ec8] and [0xae2c90] dates, [0xae2c88] time, [0xae2c78] last date, [0xae2cfc] last time, [0xae2d00] and [0xae2d04] leagues, default nation (id at +0 of [0xae2d08] or −1), [0xae2d10] × 0x4f from [0xae2d0c], [0xae2d18] × 6 from [0xae2d14], [0xae235c] × 4 from [0xae2d1c]; bytes; reads and writes into the save (gravar_jogo)'), ('[0xae3138] opções do jogo +4: bits 0x8000 (sem compressão), 0x20000000 (rede), 0x40000000 (conferir disco antes); valor; lê (gravar_jogo)', '[0xae3138] game options +4: bits 0x8000 (no compression), 0x20000000 (network), 0x40000000 (check disk first); value; reads (gravar_jogo)'), ('[0xdd7134] sem disco, [0xdd7138] sem memória; valor; grava 1 (gravar_jogo)', '[0xdd7134] out of disk, [0xdd7138] out of memory; value; writes 1 (gravar_jogo)'), ('os globais dos subsistemas (PASSOS_DO_SAVE; [0xb6b7c8], o de Media, também é a condição do FOG_OF_WAR [0xae2a60]) e [0xb5ded8] (hall da fama); ponteiro; lê (gravar_jogo)', 'the subsystem globals (PASSOS_DO_SAVE; [0xb6b7c8], the Media one, is also the FOG_OF_WAR [0xae2a60] condition) and [0xb5ded8] (hall of fame); pointer; reads (gravar_jogo)'), ('[0xdd7130] jogo gravado, [0xa801bc]; valor; grava 1 e 0; 0xdd70a0 data do último save; valor; grava (gravar_jogo)', '[0xdd7130] game saved, [0xa801bc]; value; writes 1 and 0; 0xdd70a0 last save date; value; writes (gravar_jogo)')], interessa=['SGE', 'CMRTE'])
